import time
import logging
from taf.ul.mobile.ui.android.mobiles.huawei.magic_ui_3_1_1_honor_cdy_an900 import MagicUI311HonorCdyAn900
from taf.ul.mobile.ui.android.exceptions import SlotIndexNotSupported, SelectFailure


class EMUI1010HuaWeiLioAn00(MagicUI311HonorCdyAn900):

    @staticmethod
    def _get_sim_card_on_off_position(slot_index):
        if slot_index == 0:
            return (1039, 396)
        elif slot_index == 1:
            return (1039, 636)
        else:
            raise SlotIndexNotSupported(slot_index)

    @staticmethod
    def _get_switch_sim_card_dialog_comfirm_postion():
        return (836, 2127)

    def switch_network_mode(self, mode_name, restart_time):
        if self._get_configured_network_mode_name() == mode_name:
            logging.info("has selected specified mode, no action")
            self._close_setting()
            return

        self._select_5g_network_mode(mode_name)
        time.sleep(restart_time)

        if self._get_configured_network_mode_name() != mode_name:
            raise SelectFailure(mode_name)

        self._close_setting()

    def _select_5g_network_mode(self, mode_name):
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()
        self._click_menu(mode_name)

    def _get_configured_network_mode_name(self):
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()
        return self._get_selected_node_title_in_dialog()
